public String getPassword(String username) throws UserNotFoundException {
  if (!supportsPasswordRetrieval()) {
    throw new UnsupportedOperationException();
  }
  Connection con = null;
  PreparedStatement pstmt = null;
  try {
    con = DbConnectionManager.getConnection();
    pstmt = con.prepareStatement(LOAD_PASSWORD);
    pstmt.setString(1, username);
    ResultSet rs = pstmt.executeQuery();
    if (!rs.next()) {
      throw new UserNotFoundException(username);
    }
    String plainText = rs.getString(1);
    String encrypted = rs.getString(2);
    if (encrypted != null) {
      try {
        Blowfish cipher = getCipher();
        if (cipher != null) {
          return cipher.decryptString(encrypted);
        }
      } catch (LinkageError | ExceptionInInitializerError e) {
        Log.error(e);
        throw new RuntimeException("Failed to get cipher", e);
      } catch (IndexOutOfBoundsException e) {
        Log.error(e);
        throw new RuntimeException("Failed to decrypt string", e);
      }
    }
    return plainText;
  } catch (SQLException sqle) {
    throw new UserNotFoundException(sqle);
  } finally {
    try {
      if (pstmt != null) pstmt.close();
    } catch (Exception e) {
      Log.error(e);
    }
    try {
      if (con != null) con.close();
    } catch (Exception e) {
      Log.error(e);
    }
  }
}
